mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM RN FROM ( select dc.czry_dm as czryDm,dc.czry_mc as czryMc,dc.swjg_dm as swjgDm,ds.swjg_mc as swjgMc, nvl(aa.role_dm,'czy') as roleDm,dc.usrstate as usrState,dc.description,nvl(rr.role_mc,'普通用户') as roleMc, dc.qybz,decode(dc.qybz,'Y','是','否') as qybzMc from dm_czry dc left join sys_cfg_czry_role aa on dc.czry_dm = aa.czry_dm inner join dm_swjg ds on dc.swjg_dm = ds.swjg_dm left join dm_role rr on rr.role_dm=aa.role_dm where dc.swjg_dm like #{swjgDm}||'%' and dc.qybz='Y'
and dc.czry_dm like '%'||#{czryDm,jdbcType=VARCHAR}||'%'
and dc.czry_mc like '%'||#{czryMc,jdbcType=VARCHAR}||'%'
and (CASE WHEN aa.role_dm is null THEN 'czy' else aa.role_dm end) = #{roleDm,jdbcType=VARCHAR}
and dc.swjg_dm = #{swjgDmPramIn,jdbcType=VARCHAR}
order by dc.czry_dm ) A where 1=1
and ROWNUM <= #{end}
) WHERE 1=1
and RN >= #{start}

SELECT * FROM ( SELECT A.*, ROWNUM RN FROM ( select * from (select rownum as id, dc.czry_dm as czryDm,dc.czry_mc as czryMc,dc.swjg_dm as swjgDm,ds.swjg_mc as swjgMc, dc.usrstate AS userState,dc.description, bb.qybz,decode(bb.qybz,'Y','是','否') as qybzMc,decode(fpbz,'1','接单人','') as fpbzMc,fpbz from dm_czry dc left join (select distinct qybz,czry_dm,swjg_dm,1 as fpbz from sys_cfg_czry_fpgl sc) bb on dc.czry_dm=bb.czry_dm inner join dm_swjg ds on dc.swjg_dm=ds.swjg_dm where dc.swjg_dm like #{swjgDm} || '%' and dc.usrstate in ('2','3') and dc.qybz='Y' ) zz where 1=1
and zz.czryDm like '%'||#{czryDm,jdbcType=VARCHAR}||'%'
and zz.czryMc like '%'||#{czryMc,jdbcType=VARCHAR}||'%'
order by zz.fpbz ,zz.czryDm ) A where 1=1
and ROWNUM <= #{end}
) WHERE 1=1
and RN >= #{start}

select count(*)
from sb_sbxx_hz a inner join gs_dj_cktmsdab b on (b.nsrdzdah = a.nsrdzdah)
inner join sys_dict c on (a.sbywb_dm = c.dcode and c.dtype='ywlx_dm')
inner join sys_dict d on (a.sbzt_dm = d.dcode and d.dtype='sbzt_dm')
where 1=1 and a.sbtype='ZSSB' and a.qybj='Y'

    and b.swjg_dm like #{swjgDm}||'%'


    and b.nsrmc like '%'||#{nsrmc}||'%'


    and b.qyhgdm like '%'||#{qyhgdm}||'%'


    and b.nsrsbh like '%'||#{nsrsbh}||'%'


    and to_char(a.sbrq,'yyyy-MM-dd') >=#{sbrqStart}


    and #{sbrqEnd} >= to_char(a.sbrq,'yyyy-MM-dd')


    and a.sbywb_dm=#{sbywbDm}


    and a.sbzt_dm=#{sbztDm}


    and a.sbfs=#{sbfsDm}


    and (a.sbfs=#{sbfsDm} or a.sbfs is null)


    and a.sbr=#{sbr}

select nvl(s.jd_mode,'0') as jd_mode
from sys_cfg_sbdr_filemode s
where s.codetype='GS' and s.code=#{swjgDm}

