and sbzt_dm='2A'

mapper.insert:
insert into CQSB_TXSB(CPCODE,BGD_NO,DLZM_NO,ZYFP_NO,LJ_DATE,SWCODE,OP_USER,OP_DATE,NOTE)
select mx.CPCODE,mx.BGD_NO,mx.DLZM_NO,mx.ZYFP_NO,mx.LJ_DATE,pc.SWCODE,#{opUser} as OP_USER ,#{opDate} as OP_DATE ,#{note} as NOTE
from SHQ_CQSB_SBMX  mx ,SHQ_CQSB_SBPC pc
where mx.cpcode=#{cpcode}
    and mx.sb_no=#{sbNo}
    and pc.CPCODE=mx.CPCODE
    and pc.SWCODE=#{swcode}
    and mx.cq_flag NOT  IN ('1','2','3','4','5')

